 * @hidden N
*/
scwin.fnForwdIdxCdLimit = async function () {
    /* sdd-asis-lifecycle:begin fnForwdIdxCdLimit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let flag = false;
    const forwdIdxCd = $c.util.getComponent('slc_forwdIdxCd');
    if ($c.util.getComponent("dma_EtnChangePageReq").get("forwdIdxCd") == null || $c.util.getComponent("dma_EtnChangePageReq").get("forwdIdxCd") == null) {
        return;
    }
    for (let i = 0; i < (function(){ throw 'unresolved:list:forwdIdxCdLimitList'; })(); i++) {
        if ($c.util.getComponent("dma_EtnChangePageReq").get("forwdIdxCd") === (String(((function(){ throw 'unresolved:list:forwdIdxCdLimitList'; })()) == null ? '' : ((function(){ throw 'unresolved:list:forwdIdxCdLimitList'; })())).indexOf('$' + '{') >= 0 ? '' : String(((function(){ throw 'unresolved:list:forwdIdxCdLimitList'; })()) == null ? '' : ((function(){ throw 'unresolved:list:forwdIdxCdLimitList'; })())))) {
            await $c.win.alert('선택한 지수는 보호기간(${forwdIdxCdLimitList[__i].prod_prt_end_dd}까지)이 종료 된 후에\n상장예비심사청구가 가능합니다.');
            flag = true;
        }
    }
    if (flag) {
        if ($c.util.getComponent("dma_EtnChangePageReq").get("etpIdxIndCd") === $c.util.getComponent("dma_EtnChangePageReq").get("forwdIdxCd")) {
            scwin.fnIdxCdReset();
        } else {
            forwdIdxCd[0].selected = true;
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnForwdIdxCd
 * @author Inswave
 * @date 2026. 09. 29
 * @param idxCdVal idxCdNmVal
 * @returns
 * @hidden N
*/
scwin.fnForwdIdxCd = function (idxCdVal, idxCdNmVal) {
    /* sdd-asis-lifecycle:begin fnForwdIdxCd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (idxCdVal == null || idxCdVal == null) {
        return;
    }
    const idxLvrgInvrsTpCd = idxCdVal.substring(11, 13);
    if (idxLvrgInvrsTpCd === 'P1') {
        $('select[name=forwdIdxCd]').find('option').remove();
        $('select[name=forwdIdxCd]').append('<option value="' + idxCdVal + '">' + idxCdNmVal + '</option>');
    } else {
        const readData_forwdIdxCd = $c.util.getComponent('slc_forwdIdxCd').getValue();
        $('select[name=forwdIdxCd]').find('option').remove();
        $('select[name=forwdIdxCd]').append('<option value=""></option>');
        for (let i1 = 0; i1 < (function(){ throw 'unresolved:list:forwdIdxCd'; })(); i1++) {
            const code = (String(((function(){ throw 'unresolved:list:forwdIdxCd'; })()) == null ? '' : ((function(){ throw 'unresolved:list:forwdIdxCd'; })())).indexOf('$' + '{') >= 0 ? '' : String(((function(){ throw 'unresolved:list:forwdIdxCd'; })()) == null ? '' : ((function(){ throw 'unresolved:list:forwdIdxCd'; })())));
            const nm = (String(((function(){ throw 'unresolved:list:forwdIdxCd'; })()) == null ? '' : ((function(){ throw 'unresolved:list:forwdIdxCd'; })())).indexOf('$' + '{') >= 0 ? '' : String(((function(){ throw 'unresolved:list:forwdIdxCd'; })()) == null ? '' : ((function(){ throw 'unresolved:list:forwdIdxCd'; })())));
            let selVal = '';
            if (code.substring(0, 13) === readData_forwdIdxCd.substring(0, 13)) {
                selVal = 'selected';
            }
            $('select[name=forwdIdxCd]').append('<option value="' + code + '" ' + selVal + '>' + nm + '</option>');
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
