 * @hidden N
*/
scwin.fnNewProdPrtYn = function (idxCdVal) {
    /* sdd-asis-lifecycle:begin fnNewProdPrtYn — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (idxCdVal == null || idxCdVal == null) {
        return;
    }
    const idxLvrgInvrsTpCd = idxCdVal.substring(11, 13);
    if (idxLvrgInvrsTpCd === 'P1') {
        const readData_newProdPrtYn = $c.util.getComponent('slc_newProdPrtYn').getValue();
        const readData_etp_idxIndCd = '' + dma_readDataVO.get("etp_idxIndCd") + '';
        let selVal = '';
        if ('Y' === readData_newProdPrtYn && idxCdVal.substring(0, 13) === readData_etp_idxIndCd) {
            selVal = 'selected';
        }
        $('select[name=newProdPrtYn]').find('option').remove();
        $('select[name=newProdPrtYn]').append('<option value="N">미신청</option>');
        $('select[name=newProdPrtYn]').append('<option value="Y" ' + selVal + '>신청</option>');
    } else {
        $('select[name=newProdPrtYn]').find('option').remove();
        $('select[name=newProdPrtYn]').append('<option value="N">미신청</option>');
    }
    /* sdd-asis-lifecycle:end */
};


